    level = '、'.join(rec.get('框架适配判断', [])) if rec else '通用规范补充'
    state = '、'.join(rec.get('确认状态', [])) if rec else '—'
    basis = ('REVIEW ' + rec['record_id'] + '；本次读取rev642；采纳范围和决策见验收前待明确。') if rec else c.get('来源与适用说明', '').split('\n')[0]
    rows.append([cid,c['模块／页面'],c['检查点'],refs,steps,expected,evidence,fix,prerequisite,level,state,basis])

